  1→import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
  2→import db from "../db.server";
  3→
  4→// ---------------------------------------------------------------------------
  5→// CORS
  6→// ---------------------------------------------------------------------------
  7→
  8→const CORS_HEADERS = {
  9→  "Access-Control-Allow-Origin": "*",
 10→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
 11→  "Access-Control-Allow-Headers": "Content-Type",
 12→};
 13→
 14→// ---------------------------------------------------------------------------
 15→// Validation
 16→// ---------------------------------------------------------------------------
 17→
 18→const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
 19→
 20→// ---------------------------------------------------------------------------
 21→// Types
 22→// ---------------------------------------------------------------------------
 23→
 24→interface RecommendRequestBody {
 25→  shop: string;
 26→  chartId: string;
 27→  height: number;
 28→  weight: number;
 29→  unit: "metric" | "imperial";
 30→  gender: "male" | "female" | "unisex";
 31→  bodyType: "slim" | "average" | "athletic" | "plus";
 32→}
 33→
 34→interface EstimatedMeasurements {
 35→  chest: number;
 36→  waist: number;
 37→  hips: number;
 38→  inseam: number;
 39→}
 40→
 41→interface SizeConfidence {
 42→  size: string;
 43→  confidence: number;
 44→}
 45→
 46→interface RecommendResponse {
 47→  recommendedSize: string;
 48→  confidence: number;
 49→  alternatives: SizeConfidence[];
 50→  measurements: EstimatedMeasurements;
 51→}
 52→
 53→interface ChartData {
 54→  headers: string[];
 55→  units: { default: string; available: string[] };
 56→  rows: Record<string, string>[];
 57→}
 58→
 59→// ---------------------------------------------------------------------------
 60→// Body proportion model
 61→// Based on standard anthropometric body measurement ratios.
 62→// Returns estimated measurements in inches.
 63→// ---------------------------------------------------------------------------
 64→
 65→function estimateMeasurements(
 66→  heightIn: number,
 67→  weightLbs: number,
 68→  gender: RecommendRequestBody["gender"],
 69→  bodyType: RecommendRequestBody["bodyType"],
 70→): EstimatedMeasurements {
 71→  // BMI-based body shape coefficient
 72→  const heightFt = heightIn / 12;
 73→  const bmi = (weightLbs / (heightFt * heightFt)) * 703;
 74→
 75→  // Base proportions derived from published anthropometric studies (ANSUR II)
 76→  // Chest = height * ratio + weight modifier
 77→  const bodyTypeModifiers: Record<
 78→    RecommendRequestBody["bodyType"],
 79→    { chest: number; waist: number; hips: number }
 80→  > = {
 81→    slim: { chest: -1.5, waist: -1.5, hips: -1.5 },
 82→    average: { chest: 0, waist: 0, hips: 0 },
 83→    athletic: { chest: 1.5, waist: -1.0, hips: 0.5 },
 84→    plus: { chest: 2.5, waist: 3.0, hips: 3.0 },
 85→  };
 86→
 87→  const mod = bodyTypeModifiers[bodyType];
 88→
 89→  // Gender-specific base ratios
 90→  const isFemale = gender === "female";
 91→
 92→  // Chest estimation: height coefficient + BMI scaling
 93→  const baseChest = isFemale
 94→    ? heightIn * 0.485 + bmi * 0.3
 95→    : heightIn * 0.52 + bmi * 0.28;
 96→
 97→  // Waist: smaller ratio than chest, more BMI-sensitive
 98→  const baseWaist = isFemale
 99→    ? heightIn * 0.38 + bmi * 0.38
100→    : heightIn * 0.42 + bmi * 0.36;
101→
102→  // Hips: slightly larger for female, similar to chest for male
103→  const baseHips = isFemale
104→    ? heightIn * 0.52 + bmi * 0.32
105→    : heightIn * 0.49 + bmi * 0.28;
106→
107→  // Inseam: roughly 45-47% of height
108→  const baseInseam = heightIn * (isFemale ? 0.454 : 0.47);
109→
110→  return {
111→    chest: Math.round((baseChest + mod.chest) * 10) / 10,
112→    waist: Math.round((baseWaist + mod.waist) * 10) / 10,
113→    hips: Math.round((baseHips + mod.hips) * 10) / 10,
114→    inseam: Math.round(baseInseam * 10) / 10,
115→  };
116→}
117→
118→// ---------------------------------------------------------------------------
119→// Convert height/weight to inches/lbs (imperial baseline)
120→// ---------------------------------------------------------------------------
121→
122→function toImperial(
123→  height: number,
124→  weight: number,
125→  unit: RecommendRequestBody["unit"],
126→): { heightIn: number; weightLbs: number } {
127→  if (unit === "imperial") {
128→    return { heightIn: height, weightLbs: weight };
129→  }
130→  // metric: height in cm, weight in kg
131→  return {
132→    heightIn: height / 2.54,
133→    weightLbs: weight * 2.20462,
134→  };
135→}
136→
137→// ---------------------------------------------------------------------------
138→// Parse a measurement string like "34-36" or "34" into a numeric midpoint
139→// ---------------------------------------------------------------------------
140→
141→function parseMeasurement(raw: string): number | null {
142→  if (!raw || typeof raw !== "string") return null;
143→  const cleaned = raw.trim().replace(/[^\d.-]/g, " ").trim();
144→  const parts = cleaned.split(/[\s-]+/).filter((p) => p.length > 0);
145→  const nums = parts.map(Number).filter((n) => !isNaN(n) && n > 0);
146→  if (nums.length === 0) return null;
147→  if (nums.length === 1) return nums[0];
148→  // Average of range
149→  return nums.reduce((a, b) => a + b, 0) / nums.length;
150→}
151→
152→// ---------------------------------------------------------------------------
153→// Score a single chart row against estimated measurements
154→// Returns a confidence score 0–1
155→// ---------------------------------------------------------------------------
156→
157→function scoreRow(
158→  row: Record<string, string>,
159→  measurements: EstimatedMeasurements,
160→  chartUnitsDefault: string,
161→): number {
162→  // Convert measurements to cm if the chart uses cm
163→  const factor = chartUnitsDefault === "cm" ? 2.54 : 1;
164→  const target = {
165→    chest: measurements.chest * factor,
166→    waist: measurements.waist * factor,
167→    hips: measurements.hips * factor,
168→    inseam: measurements.inseam * factor,
169→  };
170→
171→  // Map column names (case-insensitive) to measurement types
172→  const COLUMN_MAP: Record<string, keyof typeof target> = {
173→    chest: "chest",
174→    bust: "chest",
175→    waist: "waist",
176→    hips: "hips",
177→    hip: "hips",
178→    inseam: "inseam",
179→  };
180→
181→  let totalScore = 0;
182→  let scoredColumns = 0;
183→
184→  for (const [colName, cellValue] of Object.entries(row)) {
185→    const normalised = colName.toLowerCase().replace(/[^a-z]/g, "");
186→    const measureKey = COLUMN_MAP[normalised];
187→    if (!measureKey) continue;
188→
189→    const measured = parseMeasurement(cellValue);
190→    if (measured === null) continue;
191→
192→    const actual = target[measureKey];
193→    // Tolerance: ±2in (or ±5cm) scores 1.0, degrades linearly to 0 at ±6in (±15cm)
194→    const tol = chartUnitsDefault === "cm" ? 5 : 2;
195→    const maxDelta = chartUnitsDefault === "cm" ? 15 : 6;
196→    const delta = Math.abs(actual - measured);
197→    const colScore = delta <= tol ? 1.0 : Math.max(0, 1 - (delta - tol) / (maxDelta - tol));
198→
199→    totalScore += colScore;
200→    scoredColumns++;
201→  }
202→
203→  if (scoredColumns === 0) return 0;
204→  return totalScore / scoredColumns;
205→}
206→
207→// ---------------------------------------------------------------------------
208→// Main recommendation engine
209→// ---------------------------------------------------------------------------
210→
211→function recommendSize(
212→  chartData: ChartData,
213→  measurements: EstimatedMeasurements,
214→): { recommendedSize: string; confidence: number; alternatives: SizeConfidence[] } {
215→  const sizeHeader = chartData.headers.find((h) =>
216→    ["size", "size label", "label"].includes(h.toLowerCase()),
217→  );
218→
219→  if (!sizeHeader || chartData.rows.length === 0) {
220→    return { recommendedSize: "N/A", confidence: 0, alternatives: [] };
221→  }
222→
223→  const unitsDefault = chartData.units?.default ?? "in";
224→
225→  // Score each row
226→  const scored: SizeConfidence[] = chartData.rows
227→    .map((row) => {
228→      const sizeName = row[sizeHeader];
229→      if (!sizeName) return null;
230→      const confidence = Math.round(scoreRow(row, measurements, unitsDefault) * 100) / 100;
231→      return { size: sizeName, confidence };
232→    })
233→    .filter((s): s is SizeConfidence => s !== null);
234→
235→  if (scored.length === 0) {
236→    return { recommendedSize: "N/A", confidence: 0, alternatives: [] };
237→  }
238→
239→  // Sort descending by confidence
240→  scored.sort((a, b) => b.confidence - a.confidence);
241→
242→  const best = scored[0];
243→  // Alternatives: second and third best with confidence > 0.3
244→  const alternatives = scored
245→    .slice(1)
246→    .filter((s) => s.confidence > 0.3)
247→    .slice(0, 2);
248→
249→  return {
250→    recommendedSize: best.size,
251→    confidence: best.confidence,
252→    alternatives,
253→  };
254→}
