260→export const loader = async ({ request }: LoaderFunctionArgs) => {
261→  if (request.method === "OPTIONS") {
262→    return new Response(null, { status: 204, headers: CORS_HEADERS });
263→  }
264→  return Response.json(
265→    { error: "Method not allowed" },
266→    { status: 405, headers: CORS_HEADERS },
267→  );
268→};
