270→// ---------------------------------------------------------------------------
271→// Action — POST /api/recommend
272→// Body JSON: { shop, height, weight, unit, gender, bodyType, chartId }
273→// ---------------------------------------------------------------------------
274→
275→export const action = async ({ request }: ActionFunctionArgs) => {
276→  if (request.method === "OPTIONS") {
277→    return new Response(null, { status: 204, headers: CORS_HEADERS });
278→  }
279→
280→  if (request.method !== "POST") {
281→    return Response.json(
282→      { error: "Method not allowed" },
283→      { status: 405, headers: CORS_HEADERS },
284→    );
285→  }
286→
287→  let body: Partial<RecommendRequestBody>;
288→
289→  try {
290→    body = (await request.json()) as Partial<RecommendRequestBody>;
291→  } catch {
292→    return Response.json(
293→      { error: "Invalid JSON body" },
294→      { status: 400, headers: CORS_HEADERS },
295→    );
296→  }
297→
298→  const { shop, chartId, height, weight, unit, gender, bodyType } = body;
299→
300→  // Validate shop
301→  if (!shop || !SHOP_RE.test(shop)) {
302→    return Response.json(
303→      { error: "Invalid or missing shop parameter" },
304→      { status: 400, headers: CORS_HEADERS },
305→    );
306→  }
307→
308→  // Validate required fields
309→  if (!chartId) {
310→    return Response.json(
311→      { error: "chartId is required" },
312→      { status: 400, headers: CORS_HEADERS },
313→    );
314→  }
315→  if (typeof height !== "number" || height <= 0) {
316→    return Response.json(
317→      { error: "height must be a positive number" },
318→      { status: 400, headers: CORS_HEADERS },
319→    );
320→  }
321→  if (typeof weight !== "number" || weight <= 0) {
322→    return Response.json(
323→      { error: "weight must be a positive number" },
324→      { status: 400, headers: CORS_HEADERS },
325→    );
326→  }
327→  if (!unit || !["metric", "imperial"].includes(unit)) {
328→    return Response.json(
329→      { error: "unit must be 'metric' or 'imperial'" },
330→      { status: 400, headers: CORS_HEADERS },
331→    );
332→  }
333→  if (!gender || !["male", "female", "unisex"].includes(gender)) {
334→    return Response.json(
335→      { error: "gender must be 'male', 'female', or 'unisex'" },
336→      { status: 400, headers: CORS_HEADERS },
337→    );
338→  }
339→  if (!bodyType || !["slim", "average", "athletic", "plus"].includes(bodyType)) {
340→    return Response.json(
341→      { error: "bodyType must be 'slim', 'average', 'athletic', or 'plus'" },
342→      { status: 400, headers: CORS_HEADERS },
343→    );
344→  }
345→
346→  try {
347→    // Check recommender is enabled for this shop
348→    const recommenderConfig = await db.recommenderConfig.findUnique({
349→      where: { shop },
350→    });
351→
352→    if (!recommenderConfig?.enabled) {
353→      return Response.json(
354→        { error: "AI recommender is not enabled for this shop" },
355→        { status: 403, headers: CORS_HEADERS },
356→      );
357→    }
358→
359→    // Fetch the chart scoped to this shop
360→    const chart = await db.sizeChart.findFirst({
361→      where: { id: chartId, shop, status: "active" },
362→    });
363→
364→    if (!chart) {
365→      return Response.json(
366→        { error: "Chart not found" },
367→        { status: 404, headers: CORS_HEADERS },
368→      );
369→    }
370→
371→    // Parse chart data
372→    let chartData: ChartData;
373→    try {
374→      const parsed = JSON.parse(chart.data) as unknown;
375→      if (
376→        parsed !== null &&
377→        typeof parsed === "object" &&
378→        !Array.isArray(parsed)
379→      ) {
380→        const obj = parsed as Record<string, unknown>;
381→        chartData = {
382→          headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
383→          units:
384→            obj.units !== null &&
385→            typeof obj.units === "object" &&
386→            !Array.isArray(obj.units)
387→              ? (obj.units as { default: string; available: string[] })
388→              : { default: "in", available: ["in", "cm"] },
389→          rows: Array.isArray(obj.rows)
390→            ? (obj.rows as Record<string, string>[])
391→            : [],
392→        };
393→      } else {
394→        chartData = { headers: [], units: { default: "in", available: ["in", "cm"] }, rows: [] };
395→      }
396→    } catch {
397→      chartData = { headers: [], units: { default: "in", available: ["in", "cm"] }, rows: [] };
398→    }
399→
400→    // Convert inputs to imperial baseline
401→    const { heightIn, weightLbs } = toImperial(height, weight, unit);
402→
403→    // Estimate body measurements
404→    const effectiveGender: RecommendRequestBody["gender"] =
405→      gender === "unisex" ? "average" as unknown as RecommendRequestBody["gender"] : gender;
406→
407→    const measurements = estimateMeasurements(
408→      heightIn,
409→      weightLbs,
410→      effectiveGender === ("average" as unknown as RecommendRequestBody["gender"])
411→        ? "female"
412→        : effectiveGender,
413→      bodyType,
414→    );
415→
416→    // Run recommendation
417→    const { recommendedSize, confidence, alternatives } = recommendSize(
418→      chartData,
419→      measurements,
420→    );
421→
422→    const response: RecommendResponse = {
423→      recommendedSize,
424→      confidence,
425→      alternatives,
426→      measurements,
427→    };
428→
429→    return Response.json(response, { headers: CORS_HEADERS });
430→  } catch (error) {
431→    const message =
432→      error instanceof Error ? error.message : "Internal server error";
433→    return Response.json(
434→      { error: message },
435→      { status: 500, headers: CORS_HEADERS },
436→    );
437→  }
438→};
