 52→// ---------------------------------------------------------------------------
 53→// Action — POST /api/analytics-event
 54→// Body JSON: { shop, eventType, sizeChartId?, productId?, metadata? }
 55→// ---------------------------------------------------------------------------
 56→
 57→export const action = async ({ request }: ActionFunctionArgs) => {
 58→  if (request.method === "OPTIONS") {
 59→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 60→  }
 61→
 62→  if (request.method !== "POST") {
 63→    return Response.json(
 64→      { error: "Method not allowed" },
 65→      { status: 405, headers: CORS_HEADERS },
 66→    );
 67→  }
 68→
 69→  let body: Partial<AnalyticsEventBody>;
 70→
 71→  try {
 72→    body = (await request.json()) as Partial<AnalyticsEventBody>;
 73→  } catch {
 74→    return Response.json(
 75→      { error: "Invalid JSON body" },
 76→      { status: 400, headers: CORS_HEADERS },
 77→    );
 78→  }
 79→
 80→  const { shop, eventType, sizeChartId, productId, metadata } = body;
 81→
 82→  // Validate shop
 83→  if (!shop || !SHOP_RE.test(shop)) {
 84→    return Response.json(
 85→      { error: "Invalid or missing shop parameter" },
 86→      { status: 400, headers: CORS_HEADERS },
 87→    );
 88→  }
 89→
 90→  // Validate eventType
 91→  if (
 92→    !eventType ||
 93→    !(VALID_EVENT_TYPES as readonly string[]).includes(eventType)
 94→  ) {
 95→    return Response.json(
 96→      {
 97→        error: `eventType must be one of: ${VALID_EVENT_TYPES.join(", ")}`,
 98→      },
 99→      { status: 400, headers: CORS_HEADERS },
100→    );
101→  }
102→
103→  // Fire-and-forget: respond immediately and write in the background
104→  // We still await to keep error handling consistent, but we return fast
105→  // because DB writes are non-blocking in practice at this scale
106→  try {
107→    const metadataJson =
108→      metadata !== undefined && metadata !== null
109→        ? JSON.stringify(metadata)
110→        : "{}";
111→
112→    await db.analyticsEvent.create({
113→      data: {
114→        shop,
115→        eventType,
116→        sizeChartId: sizeChartId ?? null,
117→        productId: productId ?? null,
118→        metadata: metadataJson,
119→      },
120→    });
121→
122→    return Response.json({ ok: true }, { headers: CORS_HEADERS });
123→  } catch (error) {
124→    // Non-critical: tracking failures should not break the storefront
125→    // Still return 200 to avoid retries from the widget
126→    return Response.json({ ok: true }, { headers: CORS_HEADERS });
127→  }
128→};
129→

input.content:
{% comment %}
  Size Chart & Recommender — Size Chart App Block
  Renders a trigger (button, link, or side-tab) on product pages.
  Opens a fully-accessible popup or renders inline based on merchant config.
  All JS is self-contained vanilla JS — no external dependencies.
{% endcomment %}

{% liquid
  assign block_id   = block.id | replace: '-', '_'
  assign shop_domain = shop.permanent_domain
  assign product_id  = product.id | append: ''
%}

{%- comment -%} ── Inline mode container (hidden until chart loads) ──────── {%- endcomment -%}
<div
  id="scr-root-{{ block_id }}"
  class="scr-root"
  data-block-id="{{ block_id }}"
  data-shop="{{ shop_domain }}"
  data-product-id="{{ product_id }}"
  data-display-mode="{{ block.settings.display_mode }}"
  data-trigger-style="{{ block.settings.trigger_style }}"
  data-button-text="{{ block.settings.button_text | escape }}"
  data-primary-color="{{ block.settings.primary_color }}"
  data-bg-color="{{ block.settings.background_color }}"
  data-text-color="{{ block.settings.text_color }}"
  data-border-radius="{{ block.settings.border_radius }}"
>
  {%- comment -%} Trigger element — JS populates this {%- endcomment -%}
  <div id="scr-trigger-{{ block_id }}" class="scr-trigger-wrap" aria-live="polite"></div>

  {%- comment -%} Inline chart container {%- endcomment -%}
  <div
    id="scr-inline-{{ block_id }}"
    class="scr-inline-wrap"
    aria-live="polite"
    style="display:none;"
  ></div>
</div>

{%- comment -%} ── Popup portal (appended to <body> by JS) ─────────────── {%- endcomment -%}
<div
  id="scr-modal-{{ block_id }}"
  class="scr-modal"
  role="dialog"
  aria-modal="true"
  aria-labelledby="scr-modal-title-{{ block_id }}"
  tabindex="-1"
  hidden
>
  <div class="scr-modal-backdrop" data-close="true"></div>
  <div class="scr-modal-content" role="document">
    {%- comment -%} Header {%- endcomment -%}
    <div class="scr-modal-header">
      <h2 id="scr-modal-title-{{ block_id }}" class="scr-modal-title">
        {{ block.settings.button_text | escape }}
      </h2>
      <button
        class="scr-modal-close"
        type="button"
        aria-label="{{ 'general.accessibility.close' | t | default: 'Close' }}"
        data-close="true"
      >
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true" focusable="false">
          <path d="M15 5L5 15M5 5l10 10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
        </svg>
      </button>
    </div>

    {%- comment -%} Tab bar (hidden if recommender disabled) {%- endcomment -%}
    <div class="scr-tabs" role="tablist" id="scr-tabs-{{ block_id }}">
      <button
        class="scr-tab scr-tab--active"
        role="tab"
        aria-selected="true"
        aria-controls="scr-panel-chart-{{ block_id }}"
        id="scr-tab-chart-{{ block_id }}"
        data-tab="chart"
        type="button"
      >
        {{ 'products.size_chart.tab_chart' | t | default: 'Size Chart' }}
      </button>
      <button
        class="scr-tab"
        role="tab"
        aria-selected="false"
        aria-controls="scr-panel-rec-{{ block_id }}"
        id="scr-tab-rec-{{ block_id }}"
        data-tab="recommender"
        type="button"
      >
        {{ 'products.size_chart.tab_find' | t | default: 'Find My Size' }}
      </button>
    </div>

    {%- comment -%} Chart panel {%- endcomment -%}
    <div
      id="scr-panel-chart-{{ block_id }}"
      class="scr-panel scr-panel--active"
      role="tabpanel"
      aria-labelledby="scr-tab-chart-{{ block_id }}"
    >
      {%- comment -%} Unit toggle — shown only when both units available {%- endcomment -%}
      <div class="scr-unit-toggle" id="scr-unit-toggle-{{ block_id }}" hidden>
        <span class="scr-unit-label">{{ 'products.size_chart.units' | t | default: 'Units' }}:</span>
        <div class="scr-unit-btn-group" role="group" aria-label="{{ 'products.size_chart.units' | t | default: 'Units' }}">
          <button class="scr-unit-btn scr-unit-btn--active" data-unit="in" type="button">in</button>
          <button class="scr-unit-btn" data-unit="cm" type="button">cm</button>
        </div>
      </div>

      {%- comment -%} Loading state {%- endcomment -%}
      <div class="scr-loading" id="scr-chart-loading-{{ block_id }}" aria-label="{{ 'products.size_chart.loading' | t | default: 'Loading size chart' }}">
        <div class="scr-spinner" aria-hidden="true"></div>
        <p class="scr-loading-text">{{ 'products.size_chart.loading' | t | default: 'Loading size chart…' }}</p>
      </div>

      {%- comment -%} Error state {%- endcomment -%}
      <div class="scr-error" id="scr-chart-error-{{ block_id }}" hidden role="alert">
        <p class="scr-error-text">{{ 'products.size_chart.error' | t | default: 'No size chart available for this product.' }}</p>
      </div>

      {%- comment -%} Table container {%- endcomment -%}
      <div class="scr-table-wrap" id="scr-table-wrap-{{ block_id }}" hidden>
        <div class="scr-table-scroll" tabindex="0" role="region" aria-label="{{ 'products.size_chart.table_label' | t | default: 'Size chart table, scroll horizontally for more columns' }}">
          <table class="scr-table" id="scr-table-{{ block_id }}">
            <thead class="scr-table-head" id="scr-table-head-{{ block_id }}"></thead>
            <tbody class="scr-table-body" id="scr-table-body-{{ block_id }}"></tbody>
          </table>
        </div>
        <p class="scr-scroll-hint" aria-hidden="true" id="scr-scroll-hint-{{ block_id }}">
          {{ 'products.size_chart.scroll_hint' | t | default: 'Scroll right to see more' }} &rarr;
        </p>
      </div>
    </div>

    {%- comment -%} Recommender panel {%- endcomment -%}
    <div
      id="scr-panel-rec-{{ block_id }}"
      class="scr-panel"
      role="tabpanel"
      aria-labelledby="scr-tab-rec-{{ block_id }}"
      hidden
    >
      <form class="scr-rec-form" id="scr-rec-form-{{ block_id }}" novalidate>
        <div class="scr-form-row">
          {%- comment -%} Unit system {%- endcomment -%}
          <fieldset class="scr-fieldset scr-fieldset--full">
            <legend class="scr-legend">{{ 'products.size_chart.measurement_system' | t | default: 'Measurement System' }}</legend>
            <div class="scr-radio-group">
              <label class="scr-radio-label">
                <input class="scr-radio" type="radio" name="unit" value="metric" checked>
                <span>{{ 'products.size_chart.metric' | t | default: 'Metric (cm/kg)' }}</span>
              </label>
              <label class="scr-radio-label">
                <input class="scr-radio" type="radio" name="unit" value="imperial">
                <span>{{ 'products.size_chart.imperial' | t | default: 'Imperial (in/lbs)' }}</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="scr-form-row scr-form-row--two-col">
          {%- comment -%} Height {%- endcomment -%}
          <div class="scr-form-group">
            <label class="scr-label" for="scr-height-{{ block_id }}">
              {{ 'products.size_chart.height' | t | default: 'Height' }}
              <span class="scr-unit-hint" id="scr-height-unit-{{ block_id }}">(cm)</span>
            </label>
            <input
              class="scr-input"
              type="number"
              id="scr-height-{{ block_id }}"
              name="height"
              min="100"
              max="250"
              step="1"
              placeholder="170"
              required
              aria-required="true"
              aria-describedby="scr-height-err-{{ block_id }}"
            >
            <span class="scr-field-error" id="scr-height-err-{{ block_id }}" role="alert" hidden></span>
          </div>

          {%- comment -%} Weight {%- endcomment -%}
          <div class="scr-form-group">
            <label class="scr-label" for="scr-weight-{{ block_id }}">
              {{ 'products.size_chart.weight' | t | default: 'Weight' }}
              <span class="scr-unit-hint" id="scr-weight-unit-{{ block_id }}">(kg)</span>
            </label>
            <input
              class="scr-input"
              type="number"
              id="scr-weight-{{ block_id }}"
              name="weight"
              min="30"
              max="300"
              step="0.5"
              placeholder="65"
              required
              aria-required="true"
              aria-describedby="scr-weight-err-{{ block_id }}"
            >
            <span class="scr-field-error" id="scr-weight-err-{{ block_id }}" role="alert" hidden></span>
          </div>
        </div>

        <div class="scr-form-row scr-form-row--two-col">
          {%- comment -%} Gender {%- endcomment -%}
          <div class="scr-form-group">
            <label class="scr-label" for="scr-gender-{{ block_id }}">
              {{ 'products.size_chart.gender' | t | default: 'Gender' }}
            </label>
            <select class="scr-select" id="scr-gender-{{ block_id }}" name="gender" required aria-required="true">
              <option value="female">{{ 'products.size_chart.gender_female' | t | default: 'Female' }}</option>
              <option value="male">{{ 'products.size_chart.gender_male' | t | default: 'Male' }}</option>
              <option value="unisex">{{ 'products.size_chart.gender_unisex' | t | default: 'Unisex / Other' }}</option>
            </select>
          </div>

          {%- comment -%} Body type {%- endcomment -%}
          <div class="scr-form-group">
            <label class="scr-label" for="scr-bodytype-{{ block_id }}">
              {{ 'products.size_chart.body_type' | t | default: 'Body Type' }}
            </label>
            <select class="scr-select" id="scr-bodytype-{{ block_id }}" name="bodyType" required aria-required="true">
              <option value="slim">{{ 'products.size_chart.body_slim' | t | default: 'Slim / Petite' }}</option>
              <option value="average" selected>{{ 'products.size_chart.body_average' | t | default: 'Average' }}</option>
              <option value="athletic">{{ 'products.size_chart.body_athletic' | t | default: 'Athletic / Muscular' }}</option>
              <option value="plus">{{ 'products.size_chart.body_plus' | t | default: 'Plus / Curvy' }}</option>
            </select>
          </div>
        </div>

        {%- comment -%} Submit {%- endcomment -%}
        <div class="scr-form-row">
          <button class="scr-submit-btn" type="submit" id="scr-rec-submit-{{ block_id }}">
            <span class="scr-submit-text">{{ 'products.size_chart.find_my_size' | t | default: 'Find My Size' }}</span>
            <span class="scr-submit-spinner" aria-hidden="true" hidden></span>
          </button>
        </div>

        {%- comment -%} Form-level error {%- endcomment -%}
        <div class="scr-form-error" id="scr-rec-form-error-{{ block_id }}" role="alert" hidden></div>
      </form>

      {%- comment -%} Recommendation result {%- endcomment -%}
      <div
        class="scr-result"
        id="scr-rec-result-{{ block_id }}"
        aria-live="polite"
        hidden
      >
        <div class="scr-result-badge">
          <span class="scr-result-label">{{ 'products.size_chart.your_size' | t | default: 'Your Size' }}</span>
          <span class="scr-result-size" id="scr-result-size-{{ block_id }}">—</span>
        </div>
        <p class="scr-result-message" id="scr-result-msg-{{ block_id }}"></p>
        <div class="scr-result-alts" id="scr-result-alts-{{ block_id }}" hidden>
          <p class="scr-alts-label">{{ 'products.size_chart.alternatives' | t | default: 'You might also consider:' }}</p>
          <div class="scr-alts-list" id="scr-alts-list-{{ block_id }}"></div>
        </div>
        <button class="scr-redo-btn" type="button" id="scr-redo-btn-{{ block_id }}">
          {{ 'products.size_chart.recalculate' | t | default: 'Recalculate' }}
        </button>
      </div>
    </div>

    {%- comment -%} Footer {%- endcomment -%}
    <div class="scr-modal-footer">
      <span class="scr-powered-by">
        {{ 'products.size_chart.powered_by' | t | default: 'Powered by' }}
        <a
          href="https://apps.shopify.com/size-chart-recommender"
          class="scr-powered-link"
          target="_blank"
          rel="noopener noreferrer"
          aria-label="Size Chart &amp; Recommender app"
        >Size Chart &amp; Recommender</a>
      </span>
    </div>
  </div>
</div>

{%- comment -%} ══════════════════════════════════════════════════════════
  STYLES — scoped with .scr- prefix, no global pollution
══════════════════════════════════════════════════════════ {%- endcomment -%}
<style>
  /* ── Custom properties — overridden per-block via JS ── */
  #scr-root-{{ block_id }} {
    --scr-primary:    {{ block.settings.primary_color }};
    --scr-bg:         {{ block.settings.background_color }};
    --scr-text:       {{ block.settings.text_color }};
    --scr-radius:     {{ block.settings.border_radius }}px;
    --scr-success:    #16a34a;
    --scr-error:      #dc2626;
    --scr-border:     #e5e7eb;
    --scr-muted:      #6b7280;
    --scr-input-bg:   #f9fafb;
    --scr-shadow:     0 20px 60px rgba(0,0,0,.18), 0 4px 16px rgba(0,0,0,.10);
    --scr-anim:       250ms cubic-bezier(.4,0,.2,1);
  }

  /* ── Trigger ── */
  .scr-trigger-wrap { display: inline-block; }

  .scr-btn {
    display: inline-flex;
    align-items: center;
    gap: .4em;
    padding: .65em 1.4em;
    background: var(--scr-primary);
    color: #fff;
    border: 2px solid var(--scr-primary);
    border-radius: var(--scr-radius);
    font-size: 1em;
    font-weight: 600;
    line-height: 1.2;
    cursor: pointer;
    text-decoration: none;
    min-height: 44px;
    min-width: 44px;
    transition: opacity var(--scr-anim), transform var(--scr-anim);
    -webkit-font-smoothing: antialiased;
  }
  .scr-btn:hover { opacity: .87; }
  .scr-btn:active { transform: scale(.97); }
  .scr-btn:focus-visible {
    outline: 3px solid var(--scr-primary);
    outline-offset: 3px;
  }

  .scr-link-trigger {
    display: inline-flex;
    align-items: center;
    gap: .3em;
    color: var(--scr-primary);
    font-size: .95em;
    font-weight: 500;
    cursor: pointer;
    text-decoration: underline;
    background: none;
    border: none;
    padding: .4em 0;
    min-height: 44px;
    min-width: 44px;
  }
  .scr-link-trigger:focus-visible {
    outline: 3px solid var(--scr-primary);
    outline-offset: 2px;
    border-radius: 2px;
  }

  /* Side-tab trigger */
  .scr-tab-trigger {
    position: fixed;
    top: 50%;
    right: 0;
    transform: translateY(-50%) rotate(90deg);
    transform-origin: right center;
    background: var(--scr-primary);
    color: #fff;
    border: none;
    border-radius: var(--scr-radius) var(--scr-radius) 0 0;
    padding: .55em 1.1em;
    font-size: .9em;
    font-weight: 600;
    cursor: pointer;
    z-index: 9990;
    white-space: nowrap;
    min-height: 44px;
    min-width: 44px;
    writing-mode: horizontal-tb;
  }
  .scr-tab-trigger:focus-visible {
    outline: 3px solid #fff;
    outline-offset: 2px;
  }

  /* ── Inline container ── */
  .scr-inline-wrap {
    margin: 1rem 0;
    border: 1px solid var(--scr-border);
    border-radius: var(--scr-radius);
    padding: 1rem;
    background: var(--scr-bg);
    color: var(--scr-text);
  }

  /* ── Backdrop ── */
  .scr-modal {
    position: fixed;
    inset: 0;
    z-index: 99999;
    display: flex;
    align-items: flex-end;
    justify-content: center;
  }
  @media (min-width: 640px) {
    .scr-modal { align-items: center; }
  }
  .scr-modal[hidden] { display: none; }

  .scr-modal-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,.5);
    -webkit-backdrop-filter: blur(2px);
    backdrop-filter: blur(2px);
    cursor: pointer;
  }

  /* ── Modal content ── */
  .scr-modal-content {
    position: relative;
    z-index: 1;
    background: var(--scr-bg, #fff);
    color: var(--scr-text, #111);
    border-radius: var(--scr-radius, 8px) var(--scr-radius, 8px) 0 0;
    box-shadow: var(--scr-shadow);
    width: 100%;
    max-width: 560px;
    max-height: 92dvh;
    max-height: 92vh;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    animation: scrSlideUp var(--scr-anim) both;
  }
  @media (min-width: 640px) {
    .scr-modal-content {
      border-radius: var(--scr-radius, 8px);
      max-height: 88vh;
    }
  }

  @keyframes scrSlideUp {
    from { transform: translateY(40px); opacity: 0; }
    to   { transform: translateY(0);    opacity: 1; }
  }

  /* ── Header ── */
  .scr-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem .75rem;
    border-bottom: 1px solid var(--scr-border, #e5e7eb);
    flex-shrink: 0;
  }
  .scr-modal-title {
    font-size: 1.15rem;
    font-weight: 700;
    margin: 0;
    color: var(--scr-text, #111);
  }
  .scr-modal-close {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    min-height: 44px;
    min-width: 44px;
    background: none;
    border: none;
    cursor: pointer;
    border-radius: 50%;
    color: var(--scr-muted, #6b7280);
    padding: 0;
    transition: background var(--scr-anim), color var(--scr-anim);
  }
  .scr-modal-close:hover { background: var(--scr-border, #e5e7eb); color: var(--scr-text, #111); }
  .scr-modal-close:focus-visible {
    outline: 3px solid var(--scr-primary);
    outline-offset: 2px;
  }

  /* ── Tabs ── */
  .scr-tabs {
    display: flex;
    border-bottom: 1px solid var(--scr-border, #e5e7eb);
    flex-shrink: 0;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .scr-tabs::-webkit-scrollbar { display: none; }

  .scr-tab {
    flex: 1;
    padding: .7em 1em;
    font-size: .9rem;
    font-weight: 500;
    background: none;
    border: none;
    border-bottom: 2px solid transparent;
    cursor: pointer;
    color: var(--scr-muted, #6b7280);
    transition: color var(--scr-anim), border-color var(--scr-anim);
    min-height: 44px;
    white-space: nowrap;
  }
  .scr-tab--active {
    color: var(--scr-primary);
    border-bottom-color: var(--scr-primary);
    font-weight: 600;
  }
  .scr-tab:focus-visible {
    outline: 3px solid var(--scr-primary);
    outline-offset: -3px;
  }

  /* ── Panels ── */
  .scr-panel {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.25rem;
    -webkit-overflow-scrolling: touch;
  }
  .scr-panel[hidden] { display: none; }
  .scr-panel--active { display: block; }

  /* ── Unit toggle ── */
  .scr-unit-toggle {
    display: flex;
    align-items: center;
    gap: .6rem;
    margin-bottom: .75rem;
    flex-wrap: wrap;
  }
  .scr-unit-label { font-size: .85rem; color: var(--scr-muted, #6b7280); }
  .scr-unit-btn-group {
    display: flex;
    border: 1px solid var(--scr-border, #e5e7eb);
    border-radius: 6px;
    overflow: hidden;
  }
  .scr-unit-btn {
    padding: .3em .85em;
    font-size: .85rem;
    font-weight: 500;
    background: none;
    border: none;
    cursor: pointer;
    color: var(--scr-muted, #6b7280);
    transition: background var(--scr-anim), color var(--scr-anim);
    min-height: 32px;
    min-width: 44px;
  }
  .scr-unit-btn--active {
    background: var(--scr-primary);
    color: #fff;
  }
  .scr-unit-btn:focus-visible {
    outline: 3px solid var(--scr-primary);
    outline-offset: -2px;
  }

  /* ── Table ── */
  .scr-table-scroll {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    border: 1px solid var(--scr-border, #e5e7eb);
    border-radius: calc(var(--scr-radius, 8px) - 2px);
    /* Show horizontal scrollability on touch devices */
    scroll-snap-type: x proximity;
  }
  .scr-table-scroll:focus-visible {
    outline: 3px solid var(--scr-primary);
    outline-offset: 2px;
  }
