    color: var(--scr-muted, #6b7280);
  }
  .scr-result-size {
    font-size: 2.5rem;
    font-weight: 800;
    color: var(--scr-primary);
    line-height: 1;
  }
  .scr-result-message { font-size: .92rem; color: var(--scr-text, #111); margin: 0; max-width: 340px; }

  .scr-result-alts { width: 100%; }
  .scr-result-alts[hidden] { display: none; }
  .scr-alts-label { font-size: .82rem; color: var(--scr-muted, #6b7280); margin: 0 0 .4rem; }
  .scr-alts-list { display: flex; justify-content: center; gap: .5rem; flex-wrap: wrap; }
  .scr-alt-chip {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    padding: .3em .8em;
    border: 1px solid var(--scr-border, #e5e7eb);
